(3442953, 479794, 40718, '<td valign="top">tough exposure.  I don''t like that the words are bleached by the highlights.  Composition isn''t bad though. 5</td>', 'tough exposure.  I don''t like that the words are bleached by the highlights.  Composition isn''t bad though. 5', '2007-03-08 11:42:54.000000', NULL, 1),
(3442956, 476991, 40718, '<td valign="top">make sure you get 640 pixels on one side of the picture.  that will help your score greatly.  I like the idea and shot. 5</td>', 'make sure you get 640 pixels on one side of the picture.  that will help your score greatly.  I like the idea and shot. 5', '2007-03-08 11:43:26.000000', NULL, 1),
