(3451365, 480156, 16197, '<td valign="top">This looks like a magical garden and I expect to see Pan lolling around somewhere.  I would have really liked to see this early morning or early evening without such harsh light.  It has a lot of potential.</td>', 'This looks like a magical garden and I expect to see Pan lolling around somewhere.  I would have really liked to see this early morning or early evening without such harsh light.  It has a lot of potential.', '2007-03-11 22:37:55.000000', NULL, 1),
(3451369, 479580, 16197, '<td valign="top">I like this idea, but I would have loved to see a very strong gritty image with a dynamic angle.  The Idea has tons of opportunity to really make a statement.</td>', 'I like this idea, but I would have loved to see a very strong gritty image with a dynamic angle.  The Idea has tons of opportunity to really make a statement.', '2007-03-11 22:38:49.000000', NULL, 1),
(3451370, 480062, 16197, '<td valign="top">This image seems muttled to me.It is screaming for something to really make a statement.</td>', 'This image seems muttled to me.It is screaming for something to really make a statement.', '2007-03-11 22:39:27.000000', NULL, 1),
(3451373, 479538, 16197, '<td valign="top">This is a fantastic image.  I think I would have liked the model facing the mural reading the word more so than how he is now facing away.  Very dynamic image.</td>', 'This is a fantastic image.  I think I would have liked the model facing the mural reading the word more so than how he is now facing away.  Very dynamic image.', '2007-03-11 22:40:08.000000', NULL, 1),
