INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3459494, 479902, 56880, '<td valign="top">I''d like to respond to OmanOtter''s accusations that my image constitutes "hate speech."<br/> <br/>The subject, and title, refer to <b>prayer</b> being a placebo.  Studies, such as the one by the <a href="//www.ahjonline.com/article/PIIS0002870305006496/abstract" rel="nofollow" target="_blank">American Heart Journal</a> have shown at best there is no correlation between a patient knowing others are praying for them and a speedy recovery, and at worse some found that those patients fare worse on average.  A common response to this finding is "God helps those who help themselves," thus giving further support to prayer not being a substitute for actual medical care.<br/> <br/>The idea that using a Christian book is gutless, as opposed to attacking one of the other groups Mr OmarOtter lists, is laughable.  It would be gutless to attack a group which does not have the power to defend itself.  Christians, in the western world, have incredible political power.  For example, the House of Representatives passed bill HR 2679, which does not allow a plaintiff to recover their legal costs when attempting to stop government displays of Christianity.  Ann Coulter, in front of the Conservative Political Action Conference, called John Edwards a faggot, and received applause.  This behavior was not out of character for her, and she will continue to be a prominent part of Republican punditry.  Clearly, this shows it is acceptable to attack gay people.  There are still parts of this country where being openly gay can get you <a href="//www.cnn.com/US/9904/05/gay.attack.trial.03/" rel="nofollow" target="_blank">beaten to death</a>.<br/> <br/>On to the specific charge that this image, by not including references to several religions, is "hate speech."  In the context of the challenge, "Alternative Medicine," I express the idea that <b>prayer</b> is not an effective substitute for real medical care.  It can make some people feel better though, just like a placebo.  In a larger sense, however, it is important to note that criticism by itself is not intolerance.  My image does nothing to expressly or implicitly imply violence or prejudicial action against Christians.<br/> <br/>I have no problem with the fact that some people, Mr OmanOtter included, found this image offensive.  I do take issue with some of his comments directed at me.</td>', 'I''d like to respond to OmanOtter''s accusations that my image constitutes "hate speech." The subject, and title, refer to prayer being a placebo.  Studies, such as the one by the American Heart Journal have shown at best there is no correlation between a patient knowing others are praying for them and a speedy recovery, and at worse some found that those patients fare worse on average.  A common response to this finding is "God helps those who help themselves," thus giving further support to prayer not being a substitute for actual medical care. The idea that using a Christian book is gutless, as opposed to attacking one of the other groups Mr OmarOtter lists, is laughable.  It would be gutless to attack a group which does not have the power to defend itself.  Christians, in the western world, have incredible political power.  For example, the House of Representatives passed bill HR 2679, which does not allow a plaintiff to recover their legal costs when attempting to stop government displays of Christianity.  Ann Coulter, in front of the Conservative Political Action Conference, called John Edwards a faggot, and received applause.  This behavior was not out of character for her, and she will continue to be a prominent part of Republican punditry.  Clearly, this shows it is acceptable to attack gay people.  There are still parts of this country where being openly gay can get you beaten to death. On to the specific charge that this image, by not including references to several religions, is "hate speech."  In the context of the challenge, "Alternative Medicine," I express the idea that prayer is not an effective substitute for real medical care.  It can make some people feel better though, just like a placebo.  In a larger sense, however, it is important to note that criticism by itself is not intolerance.  My image does nothing to expressly or implicitly imply violence or prejudicial action against Christians. I have no problem with the fact that some people, Mr OmanOtter included, found this image offensive.  I do take issue with some of his comments directed at me.', '2007-03-14 09:16:28.000000', NULL, 0),
